from collections import namedtuple
from taf.analyzer.pdml import PdmlReader
import re


def extract(regex):
    """
    Creates a function that extracts a specific group from a string using a regular expression.

    The returned function takes a list of XPath results, applies the regular expression to the first result,
    and returns the first matching group.

    :param str regex: The regular expression pattern to use for extraction.

    :return: A function that takes a list of XPath results and returns the first matching group.
    :rtype: function

    Usage Example:

    .. code-block:: python

        extract_func = extract(r'triggerType: (\\w+)')
        result = extract_func(['triggerType: example'])
        print(result)  # Output: example
    """
    def func(xpath_result):
        assert len(xpath_result) == 1, xpath_result
        groups = re.search(regex, xpath_result[0]).groups()
        assert len(groups) == 1, groups
        return groups[0]

    return func


Record = namedtuple('Record', 'type selector fields')
Record.__doc__ = """
A namedtuple representing a record specification.

Attributes:

    - type (str): The type of the record.
    - selector (str): The XPath selector to identify the record in the PDML.
    - fields (list): A list of Field namedtuples specifying the fields to extract from the record.
"""

Field = namedtuple('Field', 'name xpath func', defaults=(extract('(.*)'),))
Field.__doc__ = """
A namedtuple representing a field specification within a record.

Attributes:

    - name (str): The name of the field.
    - xpath (str): The XPath expression to extract the field value from the record.
    - func (function): A function to process the extracted value. Defaults to a function that extracts the
      first matching group using a regular expression.
"""


def get_records(file_name, record_specs):
    """
    Get records from a PDML file according to a list of record specifications.

    record_specs are flat dicts. From which message parameters in the PDML each field of a dict shall be taken
    is specified by a list of record specifications, which mention:

        - record "type" field
        - selector (XPath), i.e., which subtree of a PDML message shall be considered
        - fields:
            - field name
            - XPath (inside subtree selected by selector) from where the field value shall be fetched
            - function, that shall be applied on the selected value, before it is stored in the record dict

    :param str file_name: PDML file path
    :param list record_specs: List of record specifications

    :return: iterator of records

    Usage Example:

    See ``record_specs.py`` in the examples directory for comprehensive record specification
    patterns and usage examples.

    """
    with open(file_name, "rb") as file_obj:
        yield from get_records_from_stream(file_obj, record_specs)


def get_records_from_stream(file_obj, record_specs):
    """
    Get records from a PDML file object according to a list of record specifications.

    record_specs are flat dicts, as described in :func:`get_records`.

    :param file_obj: PDML file stream
    :param list record_specs: List of record specifications

    :return: iterator of records

    Usage Example:

    See ``record_specs.py`` in the examples directory for comprehensive usage examples.

    """
    yield from get_records_from_pdml_entries(PdmlReader(file_obj=file_obj), record_specs)


def get_records_from_pdml_entries(pdml_entries, record_specs):
    """
    Get records from a list of PDML entries according to a list of record specifications.

    record_specs are flat dicts, as described in :func:`get_records`.

    :param Iterable pdml_entries: Iterable of PDML entries
    :param list record_specs: List of record specifications

    :return: iterator of records

    Usage Example:

    See ``record_specs.py`` in the examples directory for comprehensive usage examples.

        """
    for entry in pdml_entries:
        packet_xml = entry.packet.xml
        index = _build_index(packet_xml)
        record_dicts = _process_records(packet_xml, index, record_specs)
        for _, record_dict in sorted(record_dicts):
            yield record_dict


def _build_index(packet_xml):
    return {elem: i for i, elem in enumerate(packet_xml.iter())}


def _process_records(packet_xml, index, record_specs):
    record_dicts = []
    for record in record_specs:
        for record_xml in packet_xml.xpath(record.selector):
            record_dict = {'type': record.type}
            _add_fields(
                record_xml=record_xml,
                fields=record.fields,
                record_dict=record_dict)
            record_dicts.append((index[record_xml], record_dict))
    return record_dicts


def _add_fields(record_xml, fields, record_dict):
    for field_spec in fields:
        if xpath_result := record_xml.xpath(field_spec.xpath):
            record_dict[field_spec.name] = field_spec.func(xpath_result)
